// =====================================================================================================
// Generic helpers
// =====================================================================================================
export const BASES = 'ACGT';
export const BCOL = { A: 'green', C: 'accent', G: 'orange', T: 'red' };
export const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
export const commas = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
export const mnus = (s) => String(s).replace(/-/g, '−');
export const plural = (n, w, ws) => `${commas(n)} ${n === 1 ? w : ws || w + 's'}`;
export const COMP = { A: 'T', C: 'G', G: 'C', T: 'A' };
export const comp = (s) => s.split('').map((c) => COMP[c] || 'N').join('');
export const revcomp = (s) => comp(s).split('').reverse().join('');
/** Upper-case, U -> T, keep only A C G T. */
export const cleanDNA = (s, max = 100000) => String(s || '').toUpperCase().replace(/U/g, 'T').replace(/[^ACGT]/g, '').slice(0, max);
export const hamming = (a, b) => { let d = 0; for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++; return d; };
export const binom = (n, k) => { let r = 1; for (let i = 1; i <= k; i++) r = (r * (n - k + i)) / i; return Math.round(r); };
export const fixed = (x, d = 2) => mnus(Number(x).toFixed(d));
export const log2 = (x) => Math.log(x) / Math.LN2;
/** FNV-1a seed from a string/number. */
export function hashSeed(s) { s = String(s); let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
/** Tiny seeded generator (mulberry32) so shared code does not depend on v.rng. */
export function rng(seed) {
  let a = (seed >>> 0) || 1;
  const r = () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  r.int = (n) => Math.floor(r() * n);
  r.pick = (arr) => arr[Math.floor(r() * arr.length)];
  r.normal = () => { let u = 0, v = 0; while (!u) u = r(); while (!v) v = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  return r;
}
export const randomDNA = (r, n, gc = 0.5) => { let s = ''; for (let i = 0; i < n; i++) { const x = r(); s += x < gc / 2 ? 'C' : x < gc ? 'G' : x < gc + (1 - gc) / 2 ? 'A' : 'T'; } return s; };

// =====================================================================================================
// k-mers, neighbourhoods, hash counting
// =====================================================================================================
const CODE = { A: 0, C: 1, G: 2, T: 3 };
export const encode = (s) => { let c = 0; for (let i = 0; i < s.length; i++) c = c * 4 + CODE[s[i]]; return c; };
export const decode = (c, k) => { let s = ''; for (let i = 0; i < k; i++) { s = BASES[c & 3] + s; c >>= 2; } return s; };
/** Reverse complement of an integer-coded k-mer. */
export function rcCode(c, k) { let r = 0; for (let i = 0; i < k; i++) { r = r * 4 + (3 - (c & 3)); c >>= 2; } return r; }
const maskCache = new Map();
/** XOR masks that change at most d of the k base positions (each changed position gets a non-zero 2-bit value). */
export function masks(k, d) {
  const key = k + ':' + d; if (maskCache.has(key)) return maskCache.get(key);
  const out = [0];
  const rec = (pos, left, m) => { for (let p = pos; p < k; p++) for (let v = 1; v <= 3; v++) { const mm = m | (v << (2 * p)); out.push(mm); if (left > 1) rec(p + 1, left - 1, mm); } };
  if (d > 0) rec(0, d, 0);
  maskCache.set(key, out); return out;
}
/** All strings within Hamming distance d of p (grouped by distance), by explicit enumeration. */
export function neighbors(p, d) {
  const k = p.length, out = [[p]]; for (let i = 1; i <= d; i++) out.push([]);
  const rec = (pos, cur, used) => {
    if (pos === k) { if (used > 0) out[used].push(cur); return; }
    rec(pos + 1, cur + p[pos], used);
    if (used < d) for (const c of BASES) if (c !== p[pos]) rec(pos + 1, cur + c, used + 1);
  };
  rec(0, '', 0); return out;
}
/**
 * Frequency table of all words with at most d mismatches to some k-mer of text (optionally also of its reverse complement).
 * Returns {cnt: Uint16Array(4^k) or Map, add(i)} -- an incremental counter: ct.add(i) inserts the k-mer starting at i.
 */
export function counter(text, k, d, useRc) {
  const n = 4 ** k, cnt = k <= 10 ? new Uint16Array(n) : null, map = new Map(), M = masks(k, d), touched = [];
  const codes = []; for (let i = 0; i + k <= text.length; i++) codes.push(encode(text.slice(i, i + k)));
  const bump = (c) => { if (cnt) { if (cnt[c] === 0) touched.push(c); cnt[c]++; } else map.set(c, (map.get(c) || 0) + 1); };
  const ct = {
    k, n: codes.length, inserted: 0, cnt, map, touched,
    add(i) { const c = codes[i]; for (const m of M) bump(c ^ m); if (useRc) { const r = rcCode(c, k); for (const m of M) bump(r ^ m); } ct.inserted++; },
    get(c) { return cnt ? cnt[c] : map.get(c) || 0; },
    reset() { if (cnt) for (const c of touched) cnt[c] = 0; else map.clear(); touched.length = 0; ct.inserted = 0; },
    codes,
    /** top words [{code, word, count}] sorted by count (desc) then word */
    top(m = 8) {
      const arr = []; const consider = (c, v) => { if (arr.length < m || v > arr[arr.length - 1].count || (v === arr[arr.length - 1].count && c < arr[arr.length - 1].code)) { arr.push({ code: c, count: v }); arr.sort((a, b) => b.count - a.count || a.code - b.code); if (arr.length > m) arr.pop(); } };
      if (cnt) for (const c of touched) consider(c, cnt[c]); else for (const [c, v] of map) consider(c, v);
      return arr.map((o) => ({ ...o, word: decode(o.code, k) }));
    },
    max() { let b = 0; if (cnt) for (const c of touched) if (cnt[c] > b) b = cnt[c]; else; return b; },
  };
  return ct;
}
/** Count of the most frequent word in a window (fast). */
export function maxWordCount(text, k, d, useRc) {
  const ct = counter(text, k, d, useRc); for (let i = 0; i < ct.n; i++) ct.add(i);
  let b = 0; for (const c of ct.touched) if (ct.cnt[c] > b) b = ct.cnt[c];
  ct.reset(); return b;
}
/** Occurrences (start, strand) of the pattern (within d mismatches) in text, both strands if useRc. */
export function occurrences(text, pat, d, useRc) {
  const k = pat.length, out = [], rp = revcomp(pat);
  for (let i = 0; i + k <= text.length; i++) {
    const w = text.slice(i, i + k);
    if (hamming(w, pat) <= d) out.push({ i, strand: '+' });
    else if (useRc && hamming(w, rp) <= d) out.push({ i, strand: '-' });
  }
  return out;
}

// =====================================================================================================
// Waiting times for words in random text (Conway / Guibas-Odlyzko)
// =====================================================================================================
/** Autocorrelation: lengths j (1..m) such that the first j letters equal the last j letters. */
export function overlaps(w) { const out = []; for (let j = 1; j <= w.length; j++) if (w.slice(0, j) === w.slice(w.length - j)) out.push(j); return out; }
/** Expected number of random letters (uniform alphabet of size q) until w first appears: sum of q^j over overlaps. */
export const meanWait = (w, q = 4) => overlaps(w).reduce((t, j) => t + q ** j, 0);
/** Exact P(T > t) for t = 0..tmax via the KMP automaton, uniform letters ACGT. */
export function survival(w, tmax) {
  const m = w.length, fail = [0];
  for (let i = 1, j = 0; i < m; i++) { while (j && w[i] !== w[j]) j = fail[j - 1]; if (w[i] === w[j]) j++; fail.push(j); }
  const go = (s, c) => { while (s && (s === m || w[s] !== c)) s = fail[s - 1]; return w[s] === c ? s + 1 : 0; };
  const T = Array.from({ length: m }, (_, s) => BASES.split('').map((c) => go(s, c)));
  let p = new Float64Array(m); p[0] = 1; const out = [1];
  for (let t = 1; t <= tmax; t++) { const q = new Float64Array(m); for (let s = 0; s < m; s++) if (p[s]) for (let c = 0; c < 4; c++) { const ns = T[s][c]; if (ns < m) q[ns] += p[s] / 4; } p = q; out.push(p.reduce((a, b) => a + b, 0)); }
  return out;
}
/** Simulate n first-occurrence times of word w in uniform random text (cap at cap letters). */
export function simulateWaits(r, w, n, cap = 3000) {
  const m = w.length, out = new Int32Array(n);
  for (let i = 0; i < n; i++) { let h = '', t = 0; while (t < cap) { h = (h + BASES[(r() * 4) | 0]).slice(-m); t++; if (t >= m && h === w) break; } out[i] = t; }
  return out;
}

// =====================================================================================================
// Profiles, scores, information content
// =====================================================================================================
export const emptyCounts = (k) => BASES.split('').map(() => new Array(k).fill(0));
export function countMatrix(motifs, k = motifs[0].length) { const C = emptyCounts(k); for (const m of motifs) for (let j = 0; j < k; j++) C[CODE[m[j]]][j]++; return C; }
/** Probability profile (4 rows A C G T by k columns) with `pseudo` added to every count. */
export function profileOf(motifs, k = motifs[0].length, pseudo = 0) {
  const C = countMatrix(motifs, k), t = motifs.length, den = t + 4 * pseudo;
  return C.map((row) => row.map((x) => (x + pseudo) / den));
}
export const consensusOf = (motifs, k = motifs[0].length) => { const C = countMatrix(motifs, k); let s = ''; for (let j = 0; j < k; j++) { let b = 0; for (let a = 1; a < 4; a++) if (C[a][j] > C[b][j]) b = a; s += BASES[b]; } return s; };
/** Score(Motifs): number of letters that differ from the column's most common letter. */
export function scoreMotifs(motifs, k = motifs[0].length) { const C = countMatrix(motifs, k); let s = 0; for (let j = 0; j < k; j++) s += motifs.length - Math.max(C[0][j], C[1][j], C[2][j], C[3][j]); return s; }
/** d(Pattern, Dna): sum over sequences of the minimum Hamming distance of Pattern to a k-mer of the sequence. */
export function medianDistance(pat, seqs) {
  const k = pat.length; let tot = 0;
  for (const s of seqs) { let b = k + 1; for (let i = 0; i + k <= s.length; i++) { let d = 0; for (let c = 0; c < k && d < b; c++) if (s[i + c] !== pat[c]) d++; if (d < b) b = d; } tot += b; }
  return tot;
}
export const windowProb = (prof, w) => { let p = 1; for (let j = 0; j < w.length; j++) p *= prof[CODE[w[j]]][j]; return p; };
/** Index of the first window of s with maximal profile probability. */
export function mostProbable(s, k, prof) { let best = -1, bi = 0; for (let i = 0; i + k <= s.length; i++) { const p = windowProb(prof, s.slice(i, i + k)); if (p > best) { best = p; bi = i; } } return bi; }
export function windowProbs(s, k, prof) { const o = []; for (let i = 0; i + k <= s.length; i++) o.push(windowProb(prof, s.slice(i, i + k))); return o; }
/** Information of each column in bits relative to background q (default uniform): R = sum p log2(p/q); optional small-sample correction e_n = (4-1)/(2 ln2 n). */
export function columnInfo(P, q = [0.25, 0.25, 0.25, 0.25], n = 0, correct = false) {
  const k = P[0].length, out = [];
  for (let j = 0; j < k; j++) {
    let R = 0; for (let a = 0; a < 4; a++) { const p = P[a][j]; if (p > 0) R += p * log2(p / q[a]); }
    if (correct && n > 0) R -= 3 / (2 * Math.LN2 * n);
    out.push(Math.max(0, R));
  }
  return out;
}
/** Background letter frequencies from a GC fraction. */
export const bgFromGC = (gc) => [(1 - gc) / 2, gc / 2, gc / 2, (1 - gc) / 2];

// =====================================================================================================
// Planted motif generator (seeded) and real data helpers
// =====================================================================================================
export function mutate(r, w, m) {
  const a = w.split(''), idx = []; while (idx.length < Math.min(m, a.length)) { const i = r.int(a.length); if (!idx.includes(i)) idx.push(i); }
  for (const i of idx) { let c; do c = BASES[r.int(4)]; while (c === a[i]); a[i] = c; }
  return a.join('');
}
/** t random sequences of length L with a mutated copy (exactly m substitutions) of one random k-mer planted in each. */
export function plantedData(seed, { t = 8, L = 30, k = 8, m = 2, gc = 0.5 } = {}) {
  const r = rng(seed), motif = randomDNA(r, k, 0.5), seqs = [], pos = [], sites = [];
  for (let i = 0; i < t; i++) {
    const site = mutate(r, motif, m), p = r.int(L - k + 1), bg = randomDNA(r, L - k, gc);
    seqs.push(bg.slice(0, p) + site + bg.slice(p)); pos.push(p); sites.push(site);
  }
  return { seqs, pos, motif, sites, k, name: 'planted' };
}
export function lexaData() {
  const seqs = LEXA.map((g) => g.seq), pos = LEXA.map((g) => g.pos), k = 20;
  return { seqs, pos, motif: LEXA_CONSENSUS, sites: LEXA.map((g) => g.site), k, names: LEXA.map((g) => g.name), name: 'lexa' };
}
/** Score of the 'true' motif matrix (sites at the known positions). */
export const truthScore = (D, k = D.k) => scoreMotifs(D.seqs.map((s, i) => s.slice(D.pos[i], D.pos[i] + k)), k);

// =====================================================================================================
// Motif search algorithms
// =====================================================================================================
/** Greedy motif search from a given first k-mer (start index in seqs[0]); returns frames and the chosen positions. */
export function greedyFrom(seqs, k, start, pseudo) {
  const pos = [start], frames = [], motifs = [seqs[0].slice(start, start + k)];
  frames.push({ row: 0, pos: pos.slice(), prof: null, probs: null, score: scoreMotifs(motifs, k) });
  for (let i = 1; i < seqs.length; i++) {
    const prof = profileOf(motifs, k, pseudo), probs = windowProbs(seqs[i], k, prof);
    let b = 0, bp = -1; probs.forEach((p, j) => { if (p > bp) { bp = p; b = j; } });
    pos.push(b); motifs.push(seqs[i].slice(b, b + k));
    frames.push({ row: i, pos: pos.slice(), prof, probs, pick: b, allZero: bp === 0, score: scoreMotifs(motifs, k) });
  }
  return { pos, frames, score: scoreMotifs(motifs, k) };
}
export function greedyAll(seqs, k, pseudo) {
  const scores = []; let best = null;
  for (let s = 0; s + k <= seqs[0].length; s++) { const g = greedyFrom(seqs, k, s, pseudo); scores.push(g.score); if (!best || g.score < best.score) best = { ...g, start: s }; }
  return { scores, best };
}
export const motifsAt = (seqs, pos, k) => seqs.map((s, i) => s.slice(pos[i], pos[i] + k));
/** One run of randomized motif search; returns the trajectory of {pos, score}. */
export function randomizedRun(seqs, k, r, pseudo = 1, maxIter = 200) {
  let pos = seqs.map((s) => r.int(s.length - k + 1)), best = scoreMotifs(motifsAt(seqs, pos, k), k);
  const traj = [{ pos: pos.slice(), score: best, prof: null }];
  for (let it = 0; it < maxIter; it++) {
    const prof = profileOf(motifsAt(seqs, pos, k), k, pseudo), np = seqs.map((s) => mostProbable(s, k, prof)), sc = scoreMotifs(motifsAt(seqs, np, k), k);
    if (sc < best) { best = sc; pos = np; traj.push({ pos: np.slice(), score: sc, prof }); } else break;
  }
  return { pos, score: best, traj };
}
/** Gibbs sampler: returns frames, one per iteration. */
export function gibbsRun(seqs, k, r, N, pseudo = 1) {
  const t = seqs.length; let pos = seqs.map((s) => r.int(s.length - k + 1));
  let cur = scoreMotifs(motifsAt(seqs, pos, k), k), best = cur, bestPos = pos.slice();
  const frames = [{ it: 0, pos: pos.slice(), score: cur, best, removed: -1 }];
  for (let it = 1; it <= N; it++) {
    const i = r.int(t), others = seqs.filter((_, j) => j !== i).map((s, j0) => { const j = j0 < i ? j0 : j0 + 1; return s.slice(pos[j], pos[j] + k); });
    const prof = profileOf(others, k, pseudo), probs = windowProbs(seqs[i], k, prof), tot = probs.reduce((a, b) => a + b, 0);
    let u = r() * tot, ch = probs.length - 1; for (let j = 0; j < probs.length; j++) { u -= probs[j]; if (u <= 0) { ch = j; break; } }
    const old = pos[i]; pos[i] = ch; cur = scoreMotifs(motifsAt(seqs, pos, k), k);
    if (cur < best) { best = cur; bestPos = pos.slice(); }
    frames.push({ it, pos: pos.slice(), score: cur, best, bestPos: bestPos.slice(), removed: i, old, probs: probs.map((p) => p / tot), chosen: ch, prof });
  }
  return { frames, best, bestPos };
}
/** EM for the one-occurrence-per-sequence (OOPS) motif model. Background q fixed. Returns frames with Z, theta, loglik. */
export function emRun(seqs, k, init, q, iters = 30, pseudo = 0.002) {
  const t = seqs.length, W = seqs.map((s) => s.length - k + 1);
  const x = seqs.map((s) => s.split('').map((c) => CODE[c]));
  let theta = init.map((row) => row.slice());
  const bgLL = x.reduce((a, xi) => a + xi.reduce((b, c) => b + Math.log(q[c]), 0), 0);
  const estep = (th) => {
    const Z = [], ll = []; let L = bgLL;
    for (let i = 0; i < t; i++) {
      const r = new Array(W[i]); let sum = 0;
      for (let j = 0; j < W[i]; j++) { let v = 1; for (let c = 0; c < k; c++) v *= th[x[i][j + c]][c] / q[x[i][j + c]]; r[j] = v; sum += v; }
      Z.push(r.map((v) => v / sum)); L += Math.log(sum / W[i]);
    }
    return { Z, L };
  };
  const mstep = (Z) => {
    const th = emptyCounts(k).map((row) => row.map(() => pseudo));
    for (let i = 0; i < t; i++) for (let j = 0; j < W[i]; j++) for (let c = 0; c < k; c++) th[x[i][j + c]][c] += Z[i][j];
    for (let c = 0; c < k; c++) { let s = 0; for (let a = 0; a < 4; a++) s += th[a][c]; for (let a = 0; a < 4; a++) th[a][c] /= s; }
    return th;
  };
  const frames = [];
  for (let it = 0; it <= iters; it++) {
    const { Z, L } = estep(theta);
    frames.push({ it, phase: 'E', Z, theta: theta.map((r2) => r2.slice()), ll: L });
    if (it === iters) break;
    theta = mstep(Z);
  }
  return frames;
}
/** MEME-style starting profile from a k-mer: 0.5 on the seed letter, the rest shared. */
export const seedProfile = (w) => BASES.split('').map((b) => w.split('').map((c) => (c === b ? 0.5 : 0.5 / 3)));

// =====================================================================================================
// Pixel drawing helpers (canvas coordinates in CSS pixels, y down) for stages created with x:[0,1], y:[0,1], axes:false
// =====================================================================================================
export function pxer(v, s) {
  const P = {
    s, v,
    get W() { return s.width; }, get H() { return s.height; },
    get c() { return s.ctx; },
    col: (name, a = 1) => (typeof name === 'string' && name.startsWith('rgb') ? name : v.color(name, a)),
    rect(x, y, w, h, fill, a = 1, r = 0, stroke, sw = 1.2, sa = 1) {
      const c = s.ctx; c.save(); c.beginPath();
      if (r && c.roundRect) c.roundRect(x, y, w, h, r); else c.rect(x, y, w, h);
      if (fill) { c.fillStyle = P.col(fill, a); c.fill(); }
      if (stroke) { c.strokeStyle = P.col(stroke, sa); c.lineWidth = sw; c.stroke(); }
      c.restore(); return P;
    },
    line(x0, y0, x1, y1, color = 'muted', w = 1.2, a = 1, dash) {
      const c = s.ctx; c.save(); c.beginPath(); c.moveTo(x0, y0); c.lineTo(x1, y1); c.strokeStyle = P.col(color, a); c.lineWidth = w; if (dash) c.setLineDash(dash); c.stroke(); c.restore(); return P;
    },
    path(pts, color = 'ink', w = 1.6, a = 1, close = false, fill, fa = 0.2) {
      if (!pts.length) return P;
      const c = s.ctx; c.save(); c.beginPath(); pts.forEach(([x, y], i) => (i ? c.lineTo(x, y) : c.moveTo(x, y))); if (close) c.closePath();
      if (fill) { c.fillStyle = P.col(fill, fa); c.fill(); }
      if (color) { c.strokeStyle = P.col(color, a); c.lineWidth = w; c.lineJoin = 'round'; c.stroke(); } c.restore(); return P;
    },
    dot(x, y, r, fill, a = 1, stroke, sw = 1.4) {
      const c = s.ctx; c.save(); c.beginPath(); c.arc(x, y, r, 0, 2 * Math.PI); if (fill) { c.fillStyle = P.col(fill, a); c.fill(); } if (stroke) { c.strokeStyle = P.col(stroke); c.lineWidth = sw; c.stroke(); } c.restore(); return P;
    },
    text(str, x, y, o = {}) { s.textPx(String(str), x, y, { halo: false, size: 12, ...o }); return P; },
    tri(x, y, w, color, a = 1, up = true) { return P.path(up ? [[x - w, y + w], [x + w, y + w], [x, y - w * 0.4]] : [[x - w, y - w], [x + w, y - w], [x, y + w * 0.4]], null, 0, a, true, color, a); },
  };
  return P;
}
/** Row of base tiles. o: {cw, ch, fs, alpha, marks: Map(i -> colour name), dim: (i)->bool, bold, labels} */
export function drawTiles(P, seq, x0, y0, cw, ch, o = {}) {
  const fs = o.fs || Math.max(8, Math.min(16, cw * 0.78));
  for (let i = 0; i < seq.length; i++) {
    const b = seq[i], col = o.color ? o.color(i, b) : BCOL[b] || 'muted', dim = o.dim && o.dim(i);
    const x = x0 + i * cw;
    P.rect(x + 0.5, y0, cw - 1, ch, col, dim ? 0.07 : o.alpha ?? 0.26, cw > 9 ? 3 : 1);
    if (cw >= 7) P.text(b, x + cw / 2, y0 + ch / 2 + 0.5, { size: fs, weight: o.bold ? 800 : 650, align: 'center', color: dim ? 'faint' : 'ink' });
  }
}
/** Heat colour in light/dark: t in [0,1]. */
export const heatCol = (v, t, name = 'accent') => { const [r, g, b] = v.ramp(clamp(t, 0, 1), name); return `rgb(${r | 0},${g | 0},${b | 0})`; };
/**
 * Sequence logo into stage s (axes 'box', gutter): P = 4 x L probabilities (rows A C G T), heights = R_j (bits) * p.
 * info[j] = bits of column j. o: {ymax, dim: (j)->bool}
 */
export function drawLogo(s, v, P4, info, o = {}) {
  const L = P4[0].length, c = s.ctx;
  for (let j = 0; j < L; j++) {
    const order = [0, 1, 2, 3].sort((a, b) => P4[a][j] - P4[b][j]);
    let y = 0; const xl = s.X(j + 1 - 0.46), xr = s.X(j + 1 + 0.46);
    for (const a of order) {
      const h = P4[a][j] * info[j]; if (h <= 1e-6) continue;
      const yb = s.Y(y), yt = s.Y(y + h); y += h;
      if (yb - yt < 0.8) continue;
      c.save(); c.font = '800 100px Inter, Arial, sans-serif'; c.textAlign = 'center'; c.textBaseline = 'alphabetic';
      const m = c.measureText(BASES[a]).width || 70;
      c.translate((xl + xr) / 2, yb); c.scale((xr - xl) / m, (yb - yt) / 73); c.fillStyle = v.color(BCOL[BASES[a]], o.dim && o.dim(j) ? 0.4 : 1);
      c.fillText(BASES[a], 0, 0); c.restore();
    }
  }
}

export function decodeGenome(g) {
  const n = Math.ceil(g.n / g.bin), G = new Int16Array(n), C = new Int16Array(n);
  for (let i = 0; i < n; i++) { G[i] = parseInt(g.G.substr(2 * i, 2), 36); C[i] = parseInt(g.C.substr(2 * i, 2), 36); }
  return { G, C, n, bin: g.bin, len: g.n, acc: g.acc };
}
